const cache = new Map();

// null means "use the example sketch that came with the board".
export async function presetCode(preset) {
  if (!preset || !preset.src) return null;
  if (cache.has(preset.src)) return cache.get(preset.src);
  const r = await fetch(preset.src, { cache: 'no-store' });
  if (!r.ok) throw new Error(`${preset.src} 取不到（HTTP ${r.status}），先运行 node tools/bundle.mjs`);
  const text = await r.text();
  cache.set(preset.src, text);
  return text;
}

/* ---------- serial telemetry parsing ---------- */
function fields(line, prefix) {
  const out = {};
  for (const part of line.slice(prefix.length).split(',')) {
    const i = part.indexOf('=');
    if (i > 0) out[part.slice(0, i)] = part.slice(i + 1);
  }
  return out;
}

// Newest "<PREFIX>,k=v,k=v" line in a serial transcript, or null.
export function lastTelemetryLine(text, prefix) {
  if (!text) return null;
  const lines = text.split('\n');
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line.startsWith(prefix + ',') && line.includes('=')) return line;
  }
  return null;
}

// Its fields. The line itself is exported too because the panels count frames, and
// "the transcript grew" also counts the firmware's event lines.
export function parseTelemetry(text, prefix) {
  const line = lastTelemetryLine(text, prefix);
  return line ? fields(line, prefix) : null;
}
